public int deleteNodeAndCountLeaves(TreeNode root) {
    if (root == null) return 0;

    int leftLeaves = deleteNodeAndCountLeaves(root.left);
    int rightLeaves = deleteNodeAndCountLeaves(root.right);

    int leafCount = 0;
    if (root.left == null && root.right == null) {
        leafCount = 1;
    }

    // Adjusting leaf count after deletion
    if (root.left == null || root.right == null) {
        if (root.left != null) {
            leafCount += leftLeaves;
        } else {
            leafCount += rightLeaves;
        }
    }

    return leafCount;
}
```

