import random

class IDgenerator:
    def __init__(self, start, end, count):
        self.start = start
        self.end = end
        self.count = count
        self.generated_ids = self._generate_ids()

    def _generate_ids(self):
        if self.count > (self.end - self.start + 1):
            raise ValueError("Count cannot be greater than the range size.")
        return random.sample(range(self.start, self.end + 1), self.count)

    def get_ids(self):
        return self.generated_ids
```

