An abstract data type (ADT) is a high-level description of a collection of data and the operations that can be performed on that data. It defines what operations are allowed on the data but not how they are implemented. This abstraction hides the implementation details, allowing for greater flexibility and ease of use. ADTs are often used to model real-world objects and their behaviors.

Here's an example of an ADT for a stack implemented in C++:

```cpp
#include <iostream>
using namespace std;

// Stack ADT
template <typename T>
class Stack {
private:
    struct Node {
        T data;
        Node* next;
    };

    Node* top;

public:
    Stack() : top(nullptr) {}

    ~Stack() {
        while (top != nullptr) {
            Node* temp = top;
            top = top->next;
            delete temp;
        }
    }

    void push(T value) {
        Node* newNode = new Node{value, top};
        top = newNode;
    }

    bool isEmpty() const {
        return top == nullptr;
    }

    T pop() {
        if (isEmpty()) {
            throw runtime_error("Stack is empty");
        }
        T value = top->data;
        Node* temp = top;
        top = top->next;
        delete temp;
        return value;
    }

    T peek() const {
        if (isEmpty()) {
            throw runtime_error("Stack is empty");
        }
        return top->data;
    }
};

int main() {
    Stack<int> s;
    s.push(10);
    s.push(20);
    cout << "Top element: " << s.peek() << endl; // Outputs 20
    cout << "Popped element: " << s.pop() << endl; // Outputs 20
    cout << "Is stack empty? " << (s.isEmpty() ? "Yes" : "No") << endl; // Outputs No
    cout << "Popped element: " << s.pop() << endl; // Outputs 10
    cout << "Is stack empty? " << (s.isEmpty() ? "Yes" : "No") << endl; // Outputs Yes

    return 0;
}
```

In this example, the `Stack` class represents an ADT for a stack data structure. The implementation details such as how nodes are allocated and managed are hidden from the user, who only interacts with the stack through its public interface methods (`push`, `pop`, `peek`, and `isEmpty`).

