import java.util.Scanner;

public class BinaryToDecimal {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.println("Enter a binary string:");
        String binaryString = scanner.nextLine();
        int decimalNumber = binaryToInt(binaryString);
        System.out.println("The decimal equivalent is: " + decimalNumber);
    }

    public static int binaryToInt(String binary) {
        int decimalValue = 0;
        int base = 1;

        // Reverse the binary string for easier processing
        String reversedBinary = new StringBuilder(binary).reverse().toString();

        for (int i = 0; i < reversedBinary.length(); i++) {
            if (reversedBinary.charAt(i) == '1') {
                decimalValue += base;
            }
            base = base * 2;
        }
        return decimalValue;
    }
}
```
This program takes a binary string as input and converts it to its decimal equivalent.

