import java.util.Arrays;

public class ReverseString {
    public static void main(String[] args) {
        String[] arr = {"hello", "world", "java"};
        reverseFirstString(arr);
        System.out.println(Arrays.toString(arr));
    }

    public static void reverseFirstString(String[] arr) {
        if (arr == null || arr.length == 0) return;
        char[] chars = arr[0].toCharArray();
        int start = 0;
        int end = chars.length - 1;
        while (start < end) {
            char temp = chars[start];
            chars[start] = chars[end];
            chars[end] = temp;
            start++;
            end--;
        }
        arr[0] = new String(chars);
    }
}
```
This code reverses the first string in the array `arr` while keeping the second and third strings in their original order.

